#include "nw_nw.h"

#define MATCH_SCORE 1
#define MISMATCH_SCORE -1
#define GAP_SCORE -1

void needwun(
    char SEQA[ALEN],
    char SEQB[BLEN],
    char alignedA[ALEN + BLEN],
    char alignedB[ALEN + BLEN],
    int M[(ALEN + 1) * (BLEN + 1)],
    char ptr[(ALEN + 1) * (BLEN + 1)]) {
    int i, j;
    int index;
    int trace_index;
    int up, left, diag;

    // Initialize first column
    for (i = 0; i <= ALEN; i++) {
        index = i * (BLEN + 1);
        M[index] = i * GAP_SCORE;
        ptr[index] = 'u';
    }

    // Initialize first row
    for (j = 0; j <= BLEN; j++) {
        M[j] = j * GAP_SCORE;
        ptr[j] = 'l';
    }

    // Fill matrix
    for (i = 1; i <= ALEN; i++) {
        for (j = 1; j <= BLEN; j++) {
            index = i * (BLEN + 1) + j;
            up = M[index - (BLEN + 1)] + GAP_SCORE;
            left = M[index - 1] + GAP_SCORE;
            diag = M[index - (BLEN + 1) - 1];
            if (SEQA[i - 1] == SEQB[j - 1]) {
                diag += MATCH_SCORE;
            } else {
                diag += MISMATCH_SCORE;
            }

            if (diag >= up && diag >= left) {
                M[index] = diag;
                ptr[index] = 'd';
            } else if (up >= left) {
                M[index] = up;
                ptr[index] = 'u';
            } else {
                M[index] = left;
                ptr[index] = 'l';
            }
        }
    }

    // Traceback
    trace_index = 0;
    i = ALEN;
    j = BLEN;
    while (i > 0 || j > 0) {
        index = i * (BLEN + 1) + j;
        if (i > 0 && j > 0 && ptr[index] == 'd') {
            alignedA[trace_index] = SEQA[i - 1];
            alignedB[trace_index] = SEQB[j - 1];
            i--;
            j--;
        } else if (j > 0 && ptr[index] == 'l') {
            alignedA[trace_index] = '_';
            alignedB[trace_index] = SEQB[j - 1];
            j--;
        } else if (i > 0 && ptr[index] == 'u') {
            alignedA[trace_index] = SEQA[i - 1];
            alignedB[trace_index] = '_';
            i--;
        }
        trace_index++;
    }

    // Pad rest with underscores
    while (trace_index < ALEN + BLEN) {
        alignedA[trace_index] = '_';
        alignedB[trace_index] = '_';
        trace_index++;
    }
}
